package com.luminor.tavernquest.domain.usecase.onboarding
import javax.inject.Inject
import com.luminor.tavernquest.core.time.DateProvider;import com.luminor.tavernquest.core.util.UuidProvider;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.repository.AuthRepository;import com.luminor.tavernquest.domain.repository.HeroRepository;import kotlinx.coroutines.flow.first
class CreateHeroUseCase @Inject constructor(private val repo:HeroRepository,private val ids:UuidProvider,private val time:DateProvider,private val auth:AuthRepository){suspend operator fun invoke(name:String,heroClass:HeroClass,appearance:HeroAppearance){val heroId=ids.newId();val userId=auth.currentUser.first()?.id?:heroId;repo.create(Hero(heroId,name.trim(),appearance,heroClass,0,time.nowMillis(),userId))}}
